-- Rivalites entre clubs (derbys de la meme ville et grandes rivalites, ex: Marseille - PSG) : icone
-- dans le calendrier (cf. MatchHighlightService). Paire normalisee (team1_id < team2_id), libelle
-- facultatif. Liste de depart ci-dessous, completee ensuite depuis l'appli (/api/rivalries) ; une
-- paire dont un club est introuvable est ignoree.
CREATE TABLE rivalry (
    id BIGSERIAL PRIMARY KEY,
    team1_id BIGINT NOT NULL REFERENCES team (id) ON DELETE CASCADE,
    team2_id BIGINT NOT NULL REFERENCES team (id) ON DELETE CASCADE,
    label VARCHAR(80),
    CHECK (team1_id < team2_id),
    UNIQUE (team1_id, team2_id)
);

CREATE INDEX idx_rivalry_team2 ON rivalry (team2_id);

